use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet}};use serde_json::{json,Value};use sha2::{Digest,Sha256};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn snapshot()->Value{let mut values=BTreeMap::new();for p in ["/proc/loadavg","/proc/stat","/sys/fs/cgroup/cpu.stat","/sys/fs/cgroup/cpu.max","/sys/fs/cgroup/cpuset.cpus.effective","/sys/fs/cgroup/memory.events","/sys/fs/cgroup/memory.swap.events","/sys/devices/system/cpu/cpufreq/policy0/scaling_governor","/sys/devices/system/cpu/cpufreq/policy0/scaling_cur_freq","/sys/devices/system/cpu/cpufreq/policy0/scaling_min_freq","/sys/devices/system/cpu/cpufreq/policy0/scaling_max_freq"]{if let Ok(s)=fs::read_to_string(p){values.insert(p,s);}}json!(values)}
fn cgroups()->Value{let membership=fs::read_to_string("/proc/self/cgroup").unwrap();let relative=membership.lines().find_map(|l|l.strip_prefix("0::")).unwrap();let mut p=PathBuf::from("/sys/fs/cgroup").join(relative.trim_start_matches('/'));let root=Path::new("/sys/fs/cgroup");let mut groups=BTreeMap::new();while p.starts_with(root){let mut fields=BTreeMap::new();for name in ["cpu.max","cpu.weight","cpu.stat","cgroup.controllers","memory.max","memory.events"]{if let Ok(s)=fs::read_to_string(p.join(name)){fields.insert(name,s);}}groups.insert(p.display().to_string(),fields);if p==root{break;}assert!(p.pop());}json!({"membership":membership,"ancestors":groups,"scope":"controller cgroup ancestry outside captures; no quota/cgroup mutation or per-child attribution"})}
fn main(){let r=Path::new("/tmp/zopro-identical-control");let op=std::env::args().nth(1).unwrap();if op=="reader"{let mut s=fs::read_to_string(r.join("bench.rs")).unwrap();let start=s.find("fn prepare(){").unwrap();let end=s.find("fn analyze(){").unwrap();s.replace_range(start..end,"");s=s.replace("const ROOT:&str=\"/tmp/zopro-identical-control\";","const ROOT:&str=\"/tmp/zopro-identical-control/corrected-run\";").replace("assert_eq!(ids.len(),5770)","assert_eq!(ids.len(),5826)").replace("\"next_prior_proof_count\":5770","\"next_prior_proof_count\":5826");let main=s.find("fn main(){").unwrap();s.truncate(main);s.push_str("fn main(){assert_eq!(std::env::args().nth(1).as_deref(),Some(\"analyze\"));analyze();}\n");fs::write(r.join("corrected-analysis.rs"),s).unwrap();return;}
 if op=="after"{save(r.join("corrected-run/cgroup-after.json"),&cgroups());return;}
 assert_eq!(op,"prepare");assert_eq!(read(r.join("performance/result.json"))["status"],"complete");assert_eq!(read(r.join("analysis.json"))["sdk_requests"],1944);let out=r.join("corrected-run");fs::create_dir(&out).unwrap();let original=read(r.join("perf-plan.json"));let mut config=original.clone();let mut prior:BTreeSet<String>=serde_json::from_value(original["prior_proof_sha256"].clone()).unwrap();assert_eq!(prior.len(),5714);let mut count=0;for(p,h)in read(r.join("proof-inventory.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());if p.ends_with(".proof"){assert!(prior.insert(h.as_str().unwrap().into()));count+=1;}}assert_eq!(count,56);assert_eq!(prior.len(),5770);
 let mut pins:BTreeMap<String,String>=serde_json::from_value(original["pins"].clone()).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h);}for name in ["isolation-repair.md","prepare-corrected.rs","prepare-corrected","corrected-analysis.rs","corrected-analysis","closeout.rs","closeout"]{let p=r.join(name);pins.insert(p.display().to_string(),hash(p));}config["pins"]=json!(pins);config["prior_proof_sha256"]=json!(prior);let mut a=original.clone();let mut b=config.clone();a.as_object_mut().unwrap().remove("pins");b.as_object_mut().unwrap().remove("pins");a.as_object_mut().unwrap().remove("prior_proof_sha256");b.as_object_mut().unwrap().remove("prior_proof_sha256");assert_eq!(a,b,"measurement protocol changed");save(out.join("protocol-repair.json"),&json!({"all_measurement_fields_equal":true,"original_prior":5714,"corrected_prior":5770,"all56original_exports_retained_and_added_to_prior":true,"only_immutable_helper_pins_and_prior_set_extended":true,"initial_series_nonconforming_build_overlap":true,"fresh_output_directory":true,"same_bounds_and_no_sample_exclusions":true}));save(out.join("perf-plan.json"),&config);save(out.join("host-before.json"),&snapshot());save(out.join("cgroup-before.json"),&cgroups());println!("Corrected SAMEprotocol54latencies2profiles prepared;allhelpersbuiltbeforecapture;prior5770");}
